#!/data/data/com.termux/files/usr/bin/bash
# SekexBot v1.10.0 for Android - one-file installer.
# Run in Termux:   bash /sdcard/Download/SekexBot_Setup.sh
# Put sekexbot-setup.conf next to this file to pre-fill keys and settings (optional).
HERE="$(cd "$(dirname "$0")" && pwd)"
if [ -z "$PREFIX" ] || [ ! -d "$PREFIX" ]; then echo "Open this file in Termux on Android."; exit 1; fi
echo "Unpacking SekexBot..."
T="${TMPDIR:-$PREFIX/tmp}/sekexbot-setup.$$"
mkdir -p "$T"
LINE=$(grep -an '^__SEKEXBOT_PAYLOAD__$' "$0" | head -1 | cut -d: -f1)
if ! tail -n +$((LINE + 1)) "$0" | base64 -d | tar -xzf - -C "$T"; then
  echo "This setup file is damaged or incomplete. Download it again."; rm -rf "$T"; exit 1
fi
[ -d "$HOME/storage" ] || termux-setup-storage >/dev/null 2>&1 || true
SEKEX_SETUP_DIR="$HERE" bash "$T/SekexBot_Android/install.sh"
rc=$?
rm -rf "$T"
exit $rc
